<?php
namespace App\Http\Controllers;
use App\Models\Goal;
use App\Models\GoalMilestone;
use App\Models\GoalReview;
use App\Models\Habit;
use App\Models\Task;
use App\Services\GoalService;
use App\Services\Identity;
use App\Services\WorkspaceContext;
use Illuminate\Http\Request;
use Illuminate\Support\Carbon;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Gate;
use Illuminate\Validation\Rule;
use Illuminate\Validation\ValidationException;
class GoalController {
 public function __construct(private WorkspaceContext $context,private GoalService $service){}
 private function workspace(Request $r){$w=$this->context->current($r);abort_unless($w->type==='personal'&&(int)$w->owner_id===(int)$r->user()->id,403);return $w;}
 private function allowed(Request $r,Goal $goal){$w=$this->workspace($r);abort_unless((int)$goal->workspace_id===(int)$w->id,404);Gate::authorize('view',$goal);return $w;}
 private function data(Request $r): array {
  return $r->validate(['title'=>'required|string|max:200','description'=>'nullable|string|max:10000','horizon'=>['required',Rule::in(Goal::HORIZONS)],'category'=>['required',Rule::in(Goal::CATEGORIES)],'due_date'=>'nullable|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:2100-12-31','target'=>'required|numeric|decimal:0,2|min:0.01|max:999999999999.99','actual'=>'required|numeric|decimal:0,2|min:0|max:999999999999.99','unit'=>'required|string|max:40','status'=>['required',Rule::in(['active','paused','completed'])],'vision'=>'nullable|string|max:4000']);
 }
 public function index(Request $r){$w=$this->workspace($r);$d=$r->validate(['horizon'=>['nullable',Rule::in(Goal::HORIZONS)],'category'=>['nullable',Rule::in(Goal::CATEGORIES)],'status'=>['nullable',Rule::in(['active','paused','completed'])]]);$q=Goal::where('workspace_id',$w->id);foreach($d as $k=>$v)if($v!==null)$q->where($k,$v);$goals=$q->latest('id')->paginate(20)->withQueryString();return view('goals.index',compact('goals','d'));}
 public function create(Request $r){$this->workspace($r);return view('goals.form',['goal'=>new Goal(['horizon'=>'year','category'=>'personal','status'=>'active','target'=>100,'actual'=>0,'unit'=>'units'])]);}
 public function store(Request $r){$w=$this->workspace($r);$d=$this->data($r);$g=DB::transaction(function()use($w,$r,$d){$this->service->lock($w,$r->user());$g=new Goal($d);$g->workspace_id=$w->id;$g->save();Identity::audit('goal_created',$r->user(),$w);return $g;});return redirect()->route('goals.show',$g);}
 public function show(Request $r,Goal $goal){$w=$this->allowed($r,$goal);$milestones=$goal->milestones()->orderBy('id')->paginate(20,['*'],'milestones');$linked=$goal->tasks()->where('tasks.workspace_id',$w->id)->orderBy('tasks.id')->paginate(20,['tasks.*'],'linked');$choices=Task::where('workspace_id',$w->id)->whereNotIn('id',DB::table('goal_tasks')->where('goal_id',$goal->id)->select('task_id'))->orderBy('title')->limit(200)->get(['id','title']);return view('goals.show',compact('goal','milestones','linked','choices'));}
 public function edit(Request $r,Goal $goal){$this->allowed($r,$goal);return view('goals.form',compact('goal'));}
 public function update(Request $r,Goal $goal){$w=$this->allowed($r,$goal);Gate::authorize('update',$goal);$d=$this->data($r);DB::transaction(function()use($w,$r,$goal,$d){$this->service->lock($w,$r->user());Goal::where('workspace_id',$w->id)->findOrFail($goal->id)->update($d);Identity::audit('goal_updated',$r->user(),$w);});return redirect()->route('goals.show',$goal);}
 public function destroy(Request $r,Goal $goal){$w=$this->allowed($r,$goal);Gate::authorize('delete',$goal);DB::transaction(function()use($w,$r,$goal){$this->service->lock($w,$r->user());Goal::where('workspace_id',$w->id)->findOrFail($goal->id)->delete();Identity::audit('goal_deleted',$r->user(),$w);});return redirect()->route('goals.index');}
 public function addMilestone(Request $r,Goal $goal){$w=$this->allowed($r,$goal);$d=$r->validate(['title'=>'required|string|max:200','due_date'=>'nullable|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:2100-12-31']);DB::transaction(function()use($w,$r,$goal,$d){$this->service->lock($w,$r->user());$g=Goal::where('workspace_id',$w->id)->findOrFail($goal->id);$g->milestones()->create($d);Identity::audit('goal_milestone_created',$r->user(),$w);});return back();}
 public function milestone(Request $r,Goal $goal,GoalMilestone $milestone){$w=$this->allowed($r,$goal);abort_unless((int)$milestone->goal_id===(int)$goal->id,404);$d=$r->validate(['completed'=>'required|boolean']);DB::transaction(function()use($w,$r,$goal,$milestone,$d){$this->service->lock($w,$r->user());$g=Goal::where('workspace_id',$w->id)->findOrFail($goal->id);$m=$g->milestones()->findOrFail($milestone->id);$m->update(['completed_at'=>$d['completed']?($m->completed_at??now()):null]);Identity::audit('goal_milestone_updated',$r->user(),$w);});return back();}
 public function deleteMilestone(Request $r,Goal $goal,GoalMilestone $milestone){$w=$this->allowed($r,$goal);abort_unless((int)$milestone->goal_id===(int)$goal->id,404);DB::transaction(function()use($w,$r,$goal,$milestone){$this->service->lock($w,$r->user());Goal::where('workspace_id',$w->id)->findOrFail($goal->id)->milestones()->findOrFail($milestone->id)->delete();Identity::audit('goal_milestone_deleted',$r->user(),$w);});return back();}
 public function link(Request $r,Goal $goal){$w=$this->allowed($r,$goal);$d=$r->validate(['task_id'=>'required|integer']);DB::transaction(function()use($w,$r,$goal,$d){$this->service->lock($w,$r->user());$g=Goal::where('workspace_id',$w->id)->findOrFail($goal->id);if(!Task::where('workspace_id',$w->id)->whereKey($d['task_id'])->exists())throw ValidationException::withMessages(['task_id'=>'Choose a task in your private workspace.']);$g->tasks()->syncWithoutDetaching([$d['task_id']]);Identity::audit('goal_task_linked',$r->user(),$w);});return back();}
 public function unlink(Request $r,Goal $goal,Task $task){$w=$this->allowed($r,$goal);abort_unless((int)$task->workspace_id===(int)$w->id,404);DB::transaction(function()use($w,$r,$goal,$task){$this->service->lock($w,$r->user());Goal::where('workspace_id',$w->id)->findOrFail($goal->id)->tasks()->detach($task->id);Identity::audit('goal_task_unlinked',$r->user(),$w);});return back();}
 public function vision(Request $r){$w=$this->workspace($r);$goals=Goal::where('workspace_id',$w->id)->whereNotNull('vision')->latest('id')->paginate(20);return view('goals.vision',compact('goals'));}
 public function reports(Request $r){$w=$this->workspace($r);$goals=Goal::where('workspace_id',$w->id)->withCount(['milestones','milestones as completed_milestones_count'=>fn($q)=>$q->whereNotNull('completed_at'),'tasks'=>fn($q)=>$q->where('tasks.workspace_id',$w->id),'tasks as completed_tasks_count'=>fn($q)=>$q->where('tasks.workspace_id',$w->id)->where('tasks.status','completed')])->orderBy('id')->paginate(20,['*'],'goals');$habits=Habit::where('workspace_id',$w->id)->orderBy('id')->paginate(20,['*'],'habits');$stats=$habits->getCollection()->mapWithKeys(fn($h)=>[$h->id=>$this->service->stats($h)]);$reviews=GoalReview::where('workspace_id',$w->id)->latest('period_start')->paginate(10,['*'],'reviews');return view('goals.reports',compact('goals','habits','stats','reviews'));}
 public function review(Request $r){$w=$this->workspace($r);$d=$r->validate(['period'=>['required',Rule::in(['week','month'])],'date'=>'required|date_format:Y-m-d|after_or_equal:2000-01-01|before_or_equal:2100-12-31','reflection'=>'required|string|max:10000']);$tz=$r->user()->timezone?:'UTC';$date=Carbon::parse($d['date'],$tz);if($date->toDateString()>now()->setTimezone($tz)->toDateString())throw ValidationException::withMessages(['date'=>'Future reviews are not allowed.']);$start=($d['period']==='week'?$date->startOfWeek(Carbon::MONDAY):$date->startOfMonth())->toDateString();DB::transaction(function()use($w,$r,$d,$start){$this->service->lock($w,$r->user());$review=GoalReview::where('workspace_id',$w->id)->where('period',$d['period'])->where('period_start',$start)->first()??new GoalReview();$review->workspace_id=$w->id;$review->fill(['period'=>$d['period'],'period_start'=>$start,'reflection'=>$d['reflection']]);$review->save();Identity::audit('goal_review_saved',$r->user(),$w);});return back();}
}
